 */
async function fetchFillableEvent(stage: string): Promise<EventVo | undefined> {
  const list = await request<EventVo[]>(`/v2.0/safety/flood/event/options?inspectionStage=${stage}`)
  return (list ?? [])[0]
}
async function fetchTemplate(kind: InspectionType, eventId?: string): Promise<FloodTemplate> {
  const stage = STAGE[kind]
  let ev = eventId
